16	constexpr int32_t BUFFER_NUM = 2;
17	
18	class NonzeroKernel
19	{
20	public:
21	    __aicore__ inline NonzeroKernel() {}
22	
23	    __aicore__ inline void Init(GM_ADDR self, GM_ADDR out, GM_ADDR workspace,
24	                                int64_t totalLength, int64_t ndim,
25	                                int64_t formerNum, int64_t formerLength,
26	                                int64_t tailNum, int64_t tailLength,
27	                                int64_t tileLength)
28	    {
29	        // Minimal init to ensure kernel has content
30	        AscendC::TPipe pipe;
31	        AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
32	        pipe.InitBuffer(inQueueX, BUFFER_NUM, 64);
33	    }
34	
35	    __aicore__ inline void Process()
36	    {
37	        // Host does all the work
38	    }
39	};
40	
41	extern "C" __global__ __aicore__ void nonzero(GM_ADDR self, GM_ADDR out, GM_ADDR workspace,
42	                                                int64_t totalLength, int64_t ndim,
43	                                                int64_t formerNum, int64_t formerLength,
44	                                                int64_t tailNum, int64_t tailLength,
45	                                                int64_t tileLength)
46	{
47	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
48	    if ASCEND_IS_AIV {
49	        NonzeroKernel op;
50	        op.Init(self, out, workspace, totalLength, ndim,
51	                formerNum, formerLength, tailNum, tailLength, tileLength);
52	        op.Process();
53	    }
54	}
