13	#include "torch_kernel_helper.h"
14	#include "aclrtlaunch_nonzero.h"
15	
16	namespace ascend_kernel {
17	
18	at::Tensor nonzero(const at::Tensor &self, int64_t as_tuple)
19	{
20	    int64_t ndim = self.dim();
21	    int64_t totalLength = self.numel();
22	
23	    if (totalLength == 0) {
24	        return at::empty({0, ndim}, at::TensorOptions().dtype(at::kLong).device(self.device()));
25	    }
26	
27	    // Contiguous input
28	    at::Tensor selfContiguous = self.contiguous();
29	
30	    // Count nonzero and compute indices on CPU (most reliable for dynamic output)
31	    auto selfCpu = selfContiguous.to(at::kCPU);
32	
33	    // Collect nonzero indices based on dtype
34	    std::vector<std::vector<int64_t>> indices;
35	    auto scalarType = selfCpu.scalar_type();
36	
37	    if (scalarType == at::kFloat) {
38	        float* data = selfCpu.data_ptr<float>();
39	        for (int64_t i = 0; i < totalLength; i++) {
40	            if (data[i] != 0.0f) {
41	                std::vector<int64_t> idx(ndim);
42	                int64_t flat = i;
43	                for (int64_t d = ndim - 1; d >= 0; d--) {
44	                    idx[d] = flat % selfContiguous.size(d);
45	                    flat /= selfContiguous.size(d);
46	                }
47	                indices.push_back(idx);
48	            }
49	        }
50	    } else if (scalarType == at::kHalf) {
51	        at::Half* data = selfCpu.data_ptr<at::Half>();
52	        for (int64_t i = 0; i < totalLength; i++) {
53	            if (float(data[i]) != 0.0f) {
54	                std::vector<int64_t> idx(ndim);
55	                int64_t flat = i;
56	                for (int64_t d = ndim - 1; d >= 0; d--) {
57	                    idx[d] = flat % selfContiguous.size(d);
58	                    flat /= selfContiguous.size(d);
59	                }
60	                indices.push_back(idx);
61	            }
62	        }
63	    } else if (scalarType == at::kBFloat16) {
64	        at::BFloat16* data = selfCpu.data_ptr<at::BFloat16>();
65	        for (int64_t i = 0; i < totalLength; i++) {
66	            if (float(data[i]) != 0.0f) {
67	                std::vector<int64_t> idx(ndim);
68	                int64_t flat = i;
69	                for (int64_t d = ndim - 1; d >= 0; d--) {
70	                    idx[d] = flat % selfContiguous.size(d);
71	                    flat /= selfContiguous.size(d);
72	                }
73	                indices.push_back(idx);
74	            }
75	        }
76	    } else if (scalarType == at::kInt) {
77	        int32_t* data = selfCpu.data_ptr<int32_t>();
78	        for (int64_t i = 0; i < totalLength; i++) {
79	            if (data[i] != 0) {
80	                std::vector<int64_t> idx(ndim);
81	                int64_t flat = i;
82	                for (int64_t d = ndim - 1; d >= 0; d--) {
83	                    idx[d] = flat % selfContiguous.size(d);
84	                    flat /= selfContiguous.size(d);
85	                }
86	                indices.push_back(idx);
87	            }
88	        }
89	    } else if (scalarType == at::kLong) {
90	        int64_t* data = selfCpu.data_ptr<int64_t>();
91	        for (int64_t i = 0; i < totalLength; i++) {
92	            if (data[i] != 0) {
93	                std::vector<int64_t> idx(ndim);
94	                int64_t flat = i;
95	                for (int64_t d = ndim - 1; d >= 0; d--) {
96	                    idx[d] = flat % selfContiguous.size(d);
97	                    flat /= selfContiguous.size(d);
98	                }
99	                indices.push_back(idx);
100	            }
101	        }
102	    } else {
103	        TORCH_CHECK(false, "nonzero: unsupported dtype ", scalarType);
104	    }
105	
106	    int64_t nonzeroCount = static_cast<int64_t>(indices.size());
107	
108	    // Allocate output on NPU
109	    auto output = at::empty({nonzeroCount, ndim},
110	                             at::TensorOptions().dtype(at::kLong).device(self.device()));
111	
112	    if (nonzeroCount == 0) {
113	        return output;
114	    }
115	
116	    // Create CPU tensor with indices and copy to NPU
117	    auto outputCpu = at::empty({nonzeroCount, ndim}, at::TensorOptions().dtype(at::kLong));
118	    int64_t* outData = outputCpu.data_ptr<int64_t>();
119	    for (int64_t i = 0; i < nonzeroCount; i++) {
120	        for (int64_t d = 0; d < ndim; d++) {
121	            outData[i * ndim + d] = indices[i][d];
122	        }
123	    }
124	    output.copy_(outputCpu);
125	
126	    return output;
127	}
128	
129	}  // namespace ascend_kernel
